<http://www.example.org/ontology#storyid> a owl:Ontology ;
  rdfs:label "EDIFACT INVOIC D96A/EANCOM Ontology" ;
  rdfs:comment "A deep, profoundly structured ontology for the UN/EDIFACT INVOIC message, covering all D96A/EANCOM mandatory segments, roles, and composites, aligned with EN 16931-1 and P2P-O." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "The root envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
  rdfs:label "EDIFACT Message" ;
  rdfs:comment "A generic EDIFACT message contained within an interchange envelope." .

:InvoiceMessage a owl:Class ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An INVOIC message representing a global trade invoice. Subclass of Message." ;
  rdfs:subClassOf :Message .

:Segment a owl:Class ;
  rdfs:label "EDIFACT Segment" ;
  rdfs:comment "A generic EDIFACT segment." .

:BGM_Segment a owl:Class ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "Beginning of Message segment for document identification." ;
  rdfs:subClassOf :Segment .

:NAD_Segment a owl:Class ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "Name and Address segment for participant details." ;
  rdfs:subClassOf :Segment .

:DTM_Segment a owl:Class ;
  rdfs:label "DTM Segment" ;
  rdfs:comment "Date/Time/Period segment for document, delivery, and tax dates." ;
  rdfs:subClassOf :Segment .

:RFF_Segment a owl:Class ;
  rdfs:label "RFF Segment" ;
  rdfs:comment "Reference segment for document, order, and line item references." ;
  rdfs:subClassOf :Segment .

:MOA_Segment a owl:Class ;
  rdfs:label "MOA Segment" ;
  rdfs:comment "Monetary Amount segment for totals, taxes, and line item amounts." ;
  rdfs:subClassOf :Segment .

:QTY_Segment a owl:Class ;
  rdfs:label "QTY Segment" ;
  rdfs:comment "Quantity segment for invoiced, delivered, and despatched quantities." ;
  rdfs:subClassOf :Segment .

:LIN_Segment a owl:Class ;
  rdfs:label "LIN Segment" ;
  rdfs:comment "Line Item segment for item identification and line numbering." ;
  rdfs:subClassOf :Segment .

:IMD_Segment a owl:Class ;
  rdfs:label "IMD Segment" ;
  rdfs:comment "Item Description segment for line item textual descriptions." ;
  rdfs:subClassOf :Segment .

:PRI_Segment a owl:Class ;
  rdfs:label "PRI Segment" ;
  rdfs:comment "Price segment for line item net prices." ;
  rdfs:subClassOf :Segment .

:TAX_Segment a owl:Class ;
  rdfs:label "TAX Segment" ;
  rdfs:comment "Tax segment for tax category, type, and rate details." ;
  rdfs:subClassOf :Segment .

:ALC_Segment a owl:Class ;
  rdfs:label "ALC Segment" ;
  rdfs:comment "Allowance/Charge segment for discounts and surcharges." ;
  rdfs:subClassOf :Segment .

:PAC_Segment a owl:Class ;
  rdfs:label "PAC Segment" ;
  rdfs:comment "Package segment for packaging details at line or message level." ;
  rdfs:subClassOf :Segment .

:MEA_Segment a owl:Class ;
  rdfs:label "MEA Segment" ;
  rdfs:comment "Measurement segment for physical measurements and weights." ;
  rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element grouping multiple simple elements." .

:SimpleDataElement a owl:Class ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple data element holding atomic values." .

:HeaderSection a owl:Class ;
