  rdfs:range :LineItem ;
  owl:inverseOf :hasItem .

:hasNetPrice a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasNetPrice" ;
  rdfs:comment "Links a LineItem to the Price (net) for that item." ;
  rdfs:domain :LineItem ;
  rdfs:range :Price ;
  owl:inverseOf :isNetPriceOf .

:isNetPriceOf a owl:ObjectProperty ;
  rdfs:label "isNetPriceOf" ;
  rdfs:comment "Inverse: Links a Price to its LineItem." ;
  rdfs:domain :Price ;
  rdfs:range :LineItem ;
  owl:inverseOf :hasNetPrice .

:hasQuantity a owl:DatatypeProperty ;
