#################################################################
# Axioms, Disjointness, and Restrictions
#################################################################

:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item, :Address .
:Segment owl:disjointWith :CompositeDataElement .

#################################################################
# General Class Axioms and Restrictions
#################################################################

:RoleAssignment owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    [ a owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :AgentRole ]
    [ a owl:Restriction ; owl:onProperty :assignedTo ; owl:someValuesFrom :Organization ]
    [ a owl:Restriction ; owl:onProperty :inInvoice ; owl:someValuesFrom :InvoiceMessage ]
  )
] .

:InvoiceMessage owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    [ a owl:Restriction ; owl:onProperty :hasHeader ; owl:someValuesFrom :HeaderSection ]
    [ a owl:Restriction ; owl:onProperty :hasDetail ; owl:someValuesFrom :DetailSection ]
    [ a owl:Restriction ; owl:onProperty :hasSummary ; owl:someValuesFrom :SummarySection ]
  )
] .

