  rdfs:label "isMOASegmentOf" ;
  rdfs:comment "Inverse: Links a MOASegment to its SummarySection." ;
  rdfs:domain :MOASegment ;
  rdfs:range :SummarySection ;
  owl:inverseOf :hasMOASegment .

:hasQTYSegment a owl:ObjectProperty ;
  rdfs:label "hasQTYSegment" ;
  rdfs:comment "Links a LineItem to its QTYSegment(s) for quantities." ;
  rdfs:domain :LineItem ;
  rdfs:range :QTYSegment ;
  owl:inverseOf :isQTYSegmentOf .

:isQTYSegmentOf a owl:ObjectProperty ;
