:isTAXSegmentOf a owl:ObjectProperty ;
  rdfs:label "isTAXSegmentOf" ;
  rdfs:comment "Inverse: Links a TAXSegment to its SummarySection." ;
  rdfs:domain :TAXSegment ;
  rdfs:range :SummarySection ;
  owl:inverseOf :hasTAXSegment .

:hasALCSegment a owl:ObjectProperty ;
  rdfs:label "hasALCSegment" ;
  rdfs:comment "Links a SummarySection to its ALCSegment(s) for allowances/charges." ;
  rdfs:domain :SummarySection ;
  rdfs:range :ALCSegment ;
  owl:inverseOf :isALCSegmentOf .

:isALCSegmentOf a owl:ObjectProperty ;
  rdfs:label "isALCSegmentOf" ;
  rdfs:comment "Inverse: Links an ALCSegment to its SummarySection." ;
  rdfs:domain :ALCSegment ;
  rdfs:range :SummarySection ;
  owl:inverseOf :hasALCSegment .

:hasPACSegment a owl:ObjectProperty ;
  rdfs:label "hasPACSegment" ;
  rdfs:comment "Links a DetailSection to its PACSegment(s) for packaging details." ;
  rdfs:domain :DetailSection ;
  rdfs:range :PACSegment ;
  owl:inverseOf :isPACSegmentOf .

:isPACSegmentOf a owl:ObjectProperty ;
  rdfs:label "isPACSegmentOf" ;
  rdfs:comment "Inverse: Links a PACSegment to its DetailSection." ;
  rdfs:domain :PACSegment ;
  rdfs:range :DetailSection ;
  owl:inverseOf :hasPACSegment .

:hasMEASegment a owl:ObjectProperty ;
  rdfs:label "hasMEASegment" ;
  rdfs:comment "Links a LineItem to its MEASegment(s) for measurements." ;
  rdfs:domain :LineItem ;
  rdfs:range :MEASegment ;
  owl:inverseOf :isMEASegmentOf .

:isMEASegmentOf a owl:ObjectProperty ;
  rdfs:label "isMEASegmentOf" ;
  rdfs:comment "Inverse: Links a MEASegment to its LineItem." ;
  rdfs:domain :MEASegment ;
  rdfs:range :LineItem ;
  owl:inverseOf :hasMEASegment .

:hasInvoiceNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "hasInvoiceNumber" ;
  rdfs:comment "The invoice's unique number." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range xsd:string .

:hasDocumentDate a owl:DatatypeProperty ;
  rdfs:label "hasDocumentDate" ;
  rdfs:comment "The date of the invoice document (use xsd:string for compliance)." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string .

:hasReferenceNumber a owl:DatatypeProperty ;
  rdfs:label "hasReferenceNumber" ;
  rdfs:comment "A reference number associated with the invoice (e.g., order or delivery note)." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string .

:hasGLN a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:label "hasGLN" ;
  rdfs:comment "A Global Location Number (GLN) identifier for an organization." ;
  rdfs:domain :Identifier ;
  rdfs:range xsd:string .

:assignedBusinessProcess a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "assignedBusinessProcess" ;
  rdfs:comment "The business process to which the invoice is assigned." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :BusinessProcess ;
  owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
  rdfs:label "isBusinessProcessOf" ;
  rdfs:comment "Inverse: Links a BusinessProcess to its InvoiceMessage." ;
  rdfs:domain :BusinessProcess ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :assignedBusinessProcess .

:hasC002 a owl:ObjectProperty ;
  rdfs:label "hasC002DocumentMessageName" ;
  rdfs:comment "Links a BGMSegment to its C002 composite for document/message name." ;
  rdfs:domain :BGMSegment ;
  rdfs:range :C002DocumentMessageName ;
  owl:inverseOf :isC002OfBGM .

:isC002OfBGM a owl:ObjectProperty ;
  rdfs:label "isC002OfBGM" ;
  rdfs:comment "Inverse: Links a C002 composite to its BGMSegment." ;
  rdfs:domain :C002DocumentMessageName ;
  rdfs:range :BGMSegment ;
  owl:inverseOf :hasC002 .

:hasC056 a owl:ObjectProperty ;
  rdfs:label "hasC056DepartmentOrEmployeeDetails" ;
  rdfs:comment "Links a NADSegment to its C056 composite for department/employee details." ;
  rdfs:domain :NADSegment ;
  rdfs:range :C056DepartmentOrEmployeeDetails ;
  owl:inverseOf :isC056OfNAD .

:isC056OfNAD a owl:ObjectProperty ;
  rdfs:label "isC056OfNAD" ;
  rdfs:comment "Inverse: Links a C056 composite to its NADSegment." ;
  rdfs:domain :C056DepartmentOrEmployeeDetails ;
  rdfs:range :NADSegment ;
  owl:inverseOf :hasC056 .

:hasC509 a owl:ObjectProperty ;
  rdfs:label "hasC509PriceInformation" ;
  rdfs:comment "Links a PRISegment to its C509 composite for price information." ;
  rdfs:domain :PRISegment ;
  rdfs:range :C509PriceInformation ;
  owl:inverseOf :isC509OfPRI .

:isC509OfPRI a owl:ObjectProperty ;
  rdfs:label "isC509OfPRI" ;
  rdfs:comment "Inverse: Links a C509 composite to its PRISegment." ;
  rdfs:domain :C509PriceInformation ;
  rdfs:range :PRISegment ;
  owl:inverseOf :hasC509 .

#################################################################
# Axioms, Disjointness, and Restrictions
#################################################################

:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item, :Address .
:Segment owl:disjointWith :CompositeDataElement .

#################################################################
# General Class Axioms and Restrictions
#################################################################

:RoleAssignment owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    [ a owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :AgentRole ]
    [ a owl:Restriction ; owl:onProperty :assignedTo ; owl:someValuesFrom :Organization ]
    [ a owl:Restriction ; owl:onProperty :inInvoice ; owl:someValuesFrom :InvoiceMessage ]
  )
] .

:InvoiceMessage owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    [ a owl:Restriction ; owl:onProperty :hasHeader ; owl:someValuesFrom :HeaderSection ]
    [ a owl:Restriction ; owl:onProperty :hasDetail ; owl:someValuesFrom :DetailSection ]
    [ a owl:Restriction ; owl:onProperty :hasSummary ; owl:someValuesFrom :SummarySection ]
  )
] .

#################################################################
# End of Ontology
#################################################################

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#storyid> a owl:Ontology ;
  rdfs:label "EDIFACT INVOIC D96A/EANCOM Ontology" ;
  rdfs:comment "A deep, profoundly structured ontology for the UN/EDIFACT INVOIC message, covering all D96A/EANCOM mandatory segments, roles, and composites, aligned with EN 16931-1 and P2P-O." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
  rdfs:label "InterchangeEnvelope" ;
  rdfs:comment "The root envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
  rdfs:label "EDIFACTMessage" ;
  rdfs:comment "A generic EDIFACT message contained within an interchange envelope." .

:InvoiceMessage a owl:Class ;
  rdfs:label "InvoiceMessage" ;
  rdfs:comment "An INVOIC message representing a global trade invoice. Subclass of Message." ;
  rdfs:subClassOf :Message .

:Segment a owl:Class ;
  rdfs:label "EDIFACTSegment" ;
  rdfs:comment "A generic EDIFACT segment." .

:BGMSegment a owl:Class ;
  rdfs:label "BGMSegment" ;
  rdfs:comment "Beginning of Message segment for document identification." ;
  rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
  rdfs:label "NADSegment" ;
  rdfs:comment "Name and Address segment for participant details." ;
  rdfs:subClassOf :Segment .

:DTMSegment a owl:Class ;
  rdfs:label "DTMSegment" ;
  rdfs:comment "Date/Time/Period segment for document, delivery, and tax dates." ;
  rdfs:subClassOf :Segment .

:RFFSegment a owl:Class ;
  rdfs:label "RFFSegment" ;
  rdfs:comment "Reference segment for document, order, and line item references." ;
  rdfs:subClassOf :Segment .

:MOASegment a owl:Class ;
  rdfs:label "MOASegment" ;
  rdfs:comment "Monetary Amount segment for totals, taxes, and line item amounts." ;
  rdfs:subClassOf :Segment .

:QTYSegment a owl:Class ;
  rdfs:label "QTYSegment" ;
  rdfs:comment "Quantity segment for invoiced, delivered, and despatched quantities." ;
  rdfs:subClassOf :Segment .

:LINSegment a owl:Class ;
  rdfs:label "LINSegment" ;
  rdfs:comment "Line Item segment for item identification and line numbering." ;
  rdfs:subClassOf :Segment .

:IMDSegment a owl:Class ;
  rdfs:label "IMDSegment" ;
  rdfs:comment "Item Description segment for line item textual descriptions." ;
  rdfs:subClassOf :Segment .

:PRISegment a owl:Class ;
  rdfs:label "PRISegment" ;
  rdfs:comment "Price segment for line item net prices." ;
  rdfs:subClassOf :Segment .

:TAXSegment a owl:Class ;
  rdfs:label "TAXSegment" ;
  rdfs:comment "Tax segment for tax category, type, and rate details." ;
  rdfs:subClassOf :Segment .

:ALCSegment a owl:Class ;
  rdfs:label "ALCSegment" ;
  rdfs:comment "Allowance/Charge segment for discounts and surcharges." ;
  rdfs:subClassOf :Segment .

:PACSegment a owl:Class ;
  rdfs:label "PACSegment" ;
  rdfs:comment "Package segment for packaging details at line or message level." ;
  rdfs:subClassOf :Segment .

:MEASegment a owl:Class ;
  rdfs:label "MEASegment" ;
  rdfs:comment "Measurement segment for physical measurements and weights." ;
  rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
  rdfs:label "CompositeDataElement" ;
  rdfs:comment "A composite data element grouping multiple simple elements." .

:SimpleDataElement a owl:Class ;
  rdfs:label "SimpleDataElement" ;
  rdfs:comment "A simple data element holding atomic values." ;
  rdfs:subClassOf :CompositeDataElement .

:HeaderSection a owl:Class ;
  rdfs:label "HeaderSection" ;
  rdfs:comment "Header section of an invoice, containing document metadata." ;
  rdfs:subClassOf :CompositeDataElement .

:DetailSection a owl:Class ;
  rdfs:label "DetailSection" ;
  rdfs:comment "Detail section listing invoice line items." ;
  rdfs:subClassOf :CompositeDataElement .

:SummarySection a owl:Class ;
  rdfs:label "SummarySection" ;
  rdfs:comment "Summary section providing invoice totals, taxes, and allowances." ;
  rdfs:subClassOf :CompositeDataElement .

:Organization a owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "A legal entity involved in the invoice (buyer, supplier, etc.)." .

:AgentRole a owl:Class ;
  rdfs:label "AgentRole" ;
  rdfs:comment "A role played by an organization in a business process (e.g., Buyer, Supplier)." .

:Address a owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "A postal or physical address associated with an organization." .

:Item a owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "A product or service described in a line item." .

:Price a owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "A monetary value assigned to an item or total." .

:Tax a owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "A tax amount or tax type applied to the invoice or line item." .

:Identifier a owl:Class ;
  rdfs:label "Identifier" ;
  rdfs:comment "A unique identifier such as a GLN (Global Location Number)." .

:BusinessProcess a owl:Class ;
  rdfs:label "BusinessProcess" ;
  rdfs:comment "A business process to which the invoice can be assigned." .

:RoleAssignment a owl:Class ;
  rdfs:label "RoleAssignment" ;
  rdfs:comment "A reification (pivot) class linking an organization, its role, and the invoice context." .

:LineItem a owl:Class ;
  rdfs:label "LineItem" ;
  rdfs:comment "A single line item within the detail section of the invoice." .

:C002DocumentMessageName a owl:Class ;
  rdfs:label "C002DocumentMessageName" ;
  rdfs:comment "Composite for document/message name in BGM segment." .

:C056DepartmentOrEmployeeDetails a owl:Class ;
  rdfs:label "C056DepartmentOrEmployeeDetails" ;
  rdfs:comment "Composite for department or employee details in NAD segment." .

:C509PriceInformation a owl:Class ;
  rdfs:label "C509PriceInformation" ;
  rdfs:comment "Composite for price information in PRI segment." .

#################################################################
# Properties (Object/Data)
#################################################################

:containsMessage a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "containsMessage" ;
  rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  owl:inverseOf :isContainedByEnvelope .

:isContainedByEnvelope a owl:ObjectProperty ;
  rdfs:label "isContainedByEnvelope" ;
  rdfs:comment "Inverse: Relates a Message to its containing InterchangeEnvelope." ;
  rdfs:domain :Message ;
  rdfs:range :InterchangeEnvelope ;
  owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
  rdfs:label "hasSegment" ;
  rdfs:comment "Relates a Message to its constituent Segments." ;
  rdfs:domain :Message ;
  rdfs:range :Segment ;
  owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
  rdfs:label "isSegmentOf" ;
  rdfs:comment "Inverse: Relates a Segment to its parent Message." ;
  rdfs:domain :Segment ;
  rdfs:range :Message ;
  owl:inverseOf :hasSegment .

:hasSection a owl:ObjectProperty ;
  rdfs:label "hasSection" ;
  rdfs:comment "Relates an InvoiceMessage to its main sections (header, detail, summary)." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :CompositeDataElement ;
  owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
  rdfs:label "isSectionOf" ;
  rdfs:comment "Inverse: Relates a CompositeDataElement to its parent InvoiceMessage." ;
  rdfs:domain :CompositeDataElement ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasSection .

:hasHeader a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasHeader" ;
  rdfs:comment "Relates an InvoiceMessage to its HeaderSection." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :HeaderSection ;
  owl:inverseOf :isHeaderOf .

:isHeaderOf a owl:ObjectProperty ;
  rdfs:label "isHeaderOf" ;
  rdfs:comment "Inverse: Relates a HeaderSection to its parent InvoiceMessage." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasHeader .

:hasDetail a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasDetail" ;
  rdfs:comment "Relates an InvoiceMessage to its DetailSection." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :DetailSection ;
  owl:inverseOf :isDetailOf .

:isDetailOf a owl:ObjectProperty ;
  rdfs:label "isDetailOf" ;
  rdfs:comment "Inverse: Relates a DetailSection to its parent InvoiceMessage." ;
  rdfs:domain :DetailSection ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasDetail .

:hasSummary a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasSummary" ;
  rdfs:comment "Relates an InvoiceMessage to its SummarySection." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :SummarySection ;
  owl:inverseOf :isSummaryOf .

:isSummaryOf a owl:ObjectProperty ;
  rdfs:label "isSummaryOf" ;
  rdfs:comment "Inverse: Relates a SummarySection to its parent InvoiceMessage." ;
  rdfs:domain :SummarySection ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasSummary .

:hasLineItem a owl:ObjectProperty ;
  rdfs:label "hasLineItem" ;
  rdfs:comment "Relates a DetailSection to its LineItems." ;
  rdfs:domain :DetailSection ;
  rdfs:range :LineItem ;
  owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
  rdfs:label "isLineItemOf" ;
  rdfs:comment "Inverse: Relates a LineItem to its parent DetailSection." ;
  rdfs:domain :LineItem ;
  rdfs:range :DetailSection ;
  owl:inverseOf :hasLineItem .

:describesOrganization a owl:ObjectProperty ;
  rdfs:label "describesOrganization" ;
  rdfs:comment "Relates a NADSegment to the Organization it describes." ;
  rdfs:domain :NADSegment ;
  rdfs:range :Organization ;
  owl:inverseOf :isDescribedByNAD .

:isDescribedByNAD a owl:ObjectProperty ;
  rdfs:label "isDescribedByNAD" ;
  rdfs:comment "Inverse: Relates an Organization to its describing NADSegment." ;
  rdfs:domain :Organization ;
  rdfs:range :NADSegment ;
  owl:inverseOf :describesOrganization .

:hasAgentRole a owl:ObjectProperty ;
  rdfs:label "hasAgentRole" ;
  rdfs:comment "Links an Organization to the AgentRole(s) it plays." ;
  rdfs:domain :Organization ;
  rdfs:range :AgentRole ;
  owl:inverseOf :isAgentRoleOf .

:isAgentRoleOf a owl:ObjectProperty ;
  rdfs:label "isAgentRoleOf" ;
  rdfs:comment "Inverse: Links an AgentRole to its Organization." ;
  rdfs:domain :AgentRole ;
  rdfs:range :Organization ;
  owl:inverseOf :hasAgentRole .

:hasAddress a owl:ObjectProperty ;
  rdfs:label "hasAddress" ;
  rdfs:comment "Links an Organization to its Address." ;
  rdfs:domain :Organization ;
  rdfs:range :Address ;
  owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
  rdfs:label "isAddressOf" ;
  rdfs:comment "Inverse: Links an Address to its Organization." ;
  rdfs:domain :Address ;
  rdfs:range :Organization ;
  owl:inverseOf :hasAddress .

:hasIdentifier a owl:ObjectProperty ;
  rdfs:label "hasIdentifier" ;
  rdfs:comment "Links an Organization to its Identifier(s) such as GLN." ;
  rdfs:domain :Organization ;
  rdfs:range :Identifier ;
  owl:inverseOf :isIdentifierOf .

:isIdentifierOf a owl:ObjectProperty ;
  rdfs:label "isIdentifierOf" ;
  rdfs:comment "Inverse: Links an Identifier to its Organization." ;
  rdfs:domain :Identifier ;
  rdfs:range :Organization ;
  owl:inverseOf :hasIdentifier .

:playsRole a owl:ObjectProperty ;
  rdfs:label "playsRole" ;
  rdfs:comment "Links a RoleAssignment to an AgentRole played by an Organization in an Invoice." ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :AgentRole ;
  owl:inverseOf :isRolePlayedByAssignment .

:isRolePlayedByAssignment a owl:ObjectProperty ;
  rdfs:label "isRolePlayedByAssignment" ;
  rdfs:comment "Inverse: Links an AgentRole to its RoleAssignment." ;
  rdfs:domain :AgentRole ;
  rdfs:range :RoleAssignment ;
  owl:inverseOf :playsRole .

:assignedTo a owl:ObjectProperty ;
  rdfs:label "assignedTo" ;
  rdfs:comment "Links a RoleAssignment to the Organization that plays the role." ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :Organization ;
  owl:inverseOf :isAssignmentOf .

:isAssignmentOf a owl:ObjectProperty ;
  rdfs:label "isAssignmentOf" ;
  rdfs:comment "Inverse: Links an Organization to its RoleAssignment." ;
  rdfs:domain :Organization ;
  rdfs:range :RoleAssignment ;
  owl:inverseOf :assignedTo .

:inInvoice a owl:ObjectProperty ;
  rdfs:label "inInvoice" ;
  rdfs:comment "Links a RoleAssignment to the InvoiceMessage context." ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasRoleAssignment .

:hasRoleAssignment a owl:ObjectProperty ;
  rdfs:label "hasRoleAssignment" ;
  rdfs:comment "Inverse: Links an InvoiceMessage to its RoleAssignment(s)." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :RoleAssignment ;
  owl:inverseOf :inInvoice .

:hasItem a owl:ObjectProperty ;
  rdfs:label "hasItem" ;
  rdfs:comment "Links a LineItem to the Item it describes." ;
  rdfs:domain :LineItem ;
  rdfs:range :Item ;
  owl:inverseOf :isItemOf .

:isItemOf a owl:ObjectProperty ;
  rdfs:label "isItemOf" ;
  rdfs:comment "Inverse: Links an Item to its LineItem." ;
  rdfs:domain :Item ;
  rdfs:range :LineItem ;
  owl:inverseOf :hasItem .

:hasNetPrice a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasNetPrice" ;
  rdfs:comment "Links a LineItem to the Price (net) for that item." ;
  rdfs:domain :LineItem ;
  rdfs:range :Price ;
  owl:inverseOf :isNetPriceOf .

:isNetPriceOf a owl:ObjectProperty ;
  rdfs:label "isNetPriceOf" ;
  rdfs:comment "Inverse: Links a Price to its LineItem." ;
  rdfs:domain :Price ;
  rdfs:range :LineItem ;
  owl:inverseOf :hasNetPrice .

:hasQuantity a owl:DatatypeProperty ;
  rdfs:label "hasQuantity" ;
  rdfs:comment "Links a LineItem to its quantity." ;
  rdfs:domain :LineItem ;
  rdfs:range xsd:decimal .

:hasTax a owl:ObjectProperty ;
  rdfs:label "hasTax" ;
  rdfs:comment "Links a SummarySection to its associated Tax details." ;
  rdfs:domain :SummarySection ;
  rdfs:range :Tax ;
  owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
  rdfs:label "isTaxOf" ;
  rdfs:comment "Inverse: Links a Tax to its SummarySection." ;
  rdfs:domain :Tax ;
  rdfs:range :SummarySection ;
  owl:inverseOf :hasTax .

:hasInvoiceAmount a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:label "hasInvoiceAmount" ;
  rdfs:comment "Links a SummarySection to the total invoice Price." ;
  rdfs:domain :SummarySection ;
  rdfs:range :Price ;
  owl:inverseOf :isInvoiceAmountOf .

:isInvoiceAmountOf a owl:ObjectProperty ;
  rdfs:label "isInvoiceAmountOf" ;
  rdfs:comment "Inverse: Links a Price to its SummarySection." ;
  rdfs:domain :Price ;
  rdfs:range :SummarySection ;
  owl:inverseOf :hasInvoiceAmount .

:hasDTMSegment a owl:ObjectProperty ;
  rdfs:label "hasDTMSegment" ;
  rdfs:comment "Links a HeaderSection to its DTMSegment(s) for document and delivery dates." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :DTMSegment ;
  owl:inverseOf :isDTMSegmentOf .

:isDTMSegmentOf a owl:ObjectProperty ;
  rdfs:label "isDTMSegmentOf" ;
  rdfs:comment "Inverse: Links a DTMSegment to its HeaderSection." ;
  rdfs:domain :DTMSegment ;
  rdfs:range :HeaderSection ;
  owl:inverseOf :hasDTMSegment .

:hasRFFSegment a owl:ObjectProperty ;
  rdfs:label "hasRFFSegment" ;
  rdfs:comment "Links a HeaderSection to its RFFSegment(s) for references." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :RFFSegment ;
  owl:inverseOf :isRFFSegmentOf .

:isRFFSegmentOf a owl:ObjectProperty ;
  rdfs:label "isRFFSegmentOf" ;
  rdfs:comment "Inverse: Links a RFFSegment to its HeaderSection." ;
  rdfs:domain :RFFSegment ;
  rdfs:range :HeaderSection ;
  owl:inverseOf :hasRFFSegment .

:hasMOASegment a owl:ObjectProperty ;
  rdfs:label "hasMOASegment" ;
  rdfs:comment "Links a SummarySection to its MOASegment(s) for monetary amounts." ;
  rdfs:domain :SummarySection ;
  rdfs:range :MOASegment ;
  owl:inverseOf :isMOASegmentOf .

:isMOASegmentOf a owl:ObjectProperty ;
  rdfs:label "isMOASegmentOf" ;
  rdfs:comment "Inverse: Links a MOASegment to its SummarySection." ;
  rdfs:domain :MOASegment ;
  rdfs:range :SummarySection ;
  owl:inverseOf :hasMOASegment .

:hasQTYSegment a owl:ObjectProperty ;
  rdfs:label "hasQTYSegment" ;
  rdfs:comment "Links a LineItem to its QTYSegment(s) for quantities." ;
  rdfs:domain :LineItem ;
  rdfs:range :QTYSegment ;
  owl:inverseOf :isQTYSegmentOf .

:isQTYSegmentOf a owl:ObjectProperty ;
  rdfs:label "isQTYSegmentOf" ;
  rdfs:comment "Inverse: Links a QTYSegment to its LineItem." ;
  rdfs:domain :QTYSegment ;
  rdfs:range :LineItem ;
  owl:inverseOf :hasQTYSegment .

:hasLINSegment a owl:ObjectProperty ;
  rdfs:label "hasLINSegment" ;
  rdfs:comment "Links a DetailSection to its LINSegment(s) for line item identification." ;
  rdfs:domain :DetailSection ;
  rdfs:range :LINSegment ;
  owl:inverseOf :isLINSegmentOf .

:isLINSegmentOf a owl:ObjectProperty ;
  rdfs:label "isLINSegmentOf" ;
  rdfs:comment "Inverse: Links a LINSegment to its DetailSection." ;
  rdfs:domain :LINSegment ;
  rdfs:range :DetailSection ;
  owl:inverseOf :hasLINSegment .

:hasIMDSegment a owl:ObjectProperty ;
  rdfs:label "hasIMDSegment" ;
  rdfs:comment "Links a LineItem to its IMDSegment(s) for item descriptions." ;
  rdfs:domain :LineItem ;
