#################################################################
# Data Properties
#################################################################

:date a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "date" ;
  rdfs:comment "A date value in the header section." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string .

:referenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "reference number" ;
  rdfs:comment "A reference number in the header section." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string .

:addressLine1 a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "address line 1" ;
  rdfs:comment "First line of a postal address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .

:addressLine2 a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "address line 2" ;
  rdfs:comment "Second line of a postal address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .

:postalCode a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "postal code" ;
  rdfs:comment "Postal code of an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .

:city a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "city" ;
  rdfs:comment "City of an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .

:country a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "country" ;
  rdfs:comment "Country of an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .

:glnCode a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "GLN code" ;
  rdfs:comment "GLN string value." ;
  rdfs:domain :GlobalLocationNumber ;
  rdfs:range xsd:string .

:itemDescription a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "item description" ;
  rdfs:comment "Description of an invoice item." ;
  rdfs:domain :Item ;
  rdfs:range xsd:string .

:netPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "net price" ;
  rdfs:comment "Net price of an item." ;
  rdfs:domain :Price ;
  rdfs:range xsd:decimal .

:quantityValue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "quantity value" ;
  rdfs:comment "Quantity value of an item." ;
  rdfs:domain :Quantity ;
  rdfs:range xsd:decimal .

:taxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "tax amount" ;
  rdfs:comment "Tax amount in the summary section." ;
  rdfs:domain :Tax ;
  rdfs:range xsd:decimal .

:invoiceTotal a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "invoice total" ;
  rdfs:comment "Total invoice amount." ;
  rdfs:domain :InvoiceAmount ;
  rdfs:range xsd:decimal .

:invoiceNumberValue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "invoice number value" ;
  rdfs:comment "Value of the invoice number." ;
  rdfs:domain :InvoiceNumber ;
  rdfs:range xsd:string .

:constraintExpression a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "constraint expression" ;
  rdfs:comment "Constraint expression for validation." ;
  rdfs:domain :ValidationConstraint ;
  rdfs:range xsd:string .

:shaclExpression a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "SHACL expression" ;
  rdfs:comment "SHACL constraint expression." ;
  rdfs:domain :SHACLConstraint ;
  rdfs:range xsd:string .

#################################################################
# Complex Axioms & Restrictions
#################################################################

:InvoiceMessage owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    :Message
    [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :HeaderSection ]
    [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :DetailSection ]
    [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :SummarySection ]
    [ a owl:Restriction ; owl:onProperty :hasInvoiceNumber ; owl:someValuesFrom :InvoiceNumber ]
    [ a owl:Restriction ; owl:onProperty :assignedToBusinessProcess ; owl:someValuesFrom :BusinessProcess ]
  )
] .

:Organization owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    [ a owl:Restriction ; owl:onProperty :hasRoleAssignment ; owl:someValuesFrom :Pivot_OrganizationRoleAssignment ]
    [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:someValuesFrom :Address ]
    [ a owl:Restriction ; owl:onProperty :hasGLN ; owl:someValuesFrom :GlobalLocationNumber ]
  )
] .

:Pivot_OrganizationRoleAssignment owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:someValuesFrom :AgentRole ]
    [ a owl:Restriction ; owl:onProperty :roleInInvoice ; owl:someValuesFrom :InvoiceMessage ]
  )
] .

#################################################################
# End of ontology
#################################################################
