<http://www.example.org/ontology#StoryID> a owl:Ontology ;
  rdfs:label "EDIFACT INVOIC Deep Structured Ontology" ;
  rdfs:comment "A profoundly structured ontology for UN/EDIFACT INVOIC messages, including D96A/EANCOM, EN16931, and P2P-O alignment." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "Top-level envelope containing all messages in an EDIFACT interchange." .

:Message a owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A contained message within an interchange envelope." .

:InvoiceMessage a owl:Class ;
  rdfs:subClassOf :Message ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An invoice (INVOIC) message in the interchange." .

:Section a owl:Class ;
  rdfs:label "Section" ;
  rdfs:comment "A general section in the invoice, superclass of HeaderSection, DetailSection, SummarySection." .

:HeaderSection a owl:Class ;
  rdfs:subClassOf :Section , :InvoiceMessage ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of the invoice, containing dates and reference numbers." .

:DetailSection a owl:Class ;
  rdfs:subClassOf :Section , :InvoiceMessage ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing line items." .

:SummarySection a owl:Class ;
  rdfs:subClassOf :Section , :InvoiceMessage ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section with totals and taxes." .

:Segment a owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within a message, such as BGM or NAD." .

:BGM a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Beginning of Message Segment" ;
  rdfs:comment "The BGM segment identifying the document type and number." .

:NAD a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Name and Address Segment" ;
  rdfs:comment "The NAD segment for participant details (e.g., buyer, supplier)." .

:CompositeDataElement a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple, atomic data element." .

:Organization a owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "Any organization involved in the invoice transaction." .

:AgentRole a owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization in the invoice context." .

:BuyerRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Buyer Role" ;
  rdfs:comment "The buyer role in the invoice." .

:DeliveryPartyRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Delivery Party Role" ;
  rdfs:comment "The delivery party role in the invoice." .

:Address a owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "A postal address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A GLN identifier for an organization location." .

:Item a owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "A line item in the invoice." .

:Price a owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "The price of an item." .

:Quantity a owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "The quantity of an item." .

:Tax a owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax information in the summary section." .

:InvoiceAmount a owl:Class ;
  rdfs:label "Invoice Amount" ;
  rdfs:comment "The total amount of the invoice." .

:InvoiceNumber a owl:Class ;
  rdfs:label "Invoice Number" ;
  rdfs:comment "The invoice's unique identifier." .

:BusinessProcess a owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "A business process to which the invoice is assigned." .

:P2PAlignment a owl:Class ;
  rdfs:label "P2P-O Alignment" ;
  rdfs:comment "Alignment with the Purchase-to-Pay Ontology." .

:EN16931Alignment a owl:Class ;
  rdfs:label "EN 16931 Alignment" ;
  rdfs:comment "Alignment with the European Standard EN 16931-1." .

:ValidationConstraint a owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "A constraint for automated validation (e.g., SHACL)." .

:SHACLConstraint a owl:Class ;
  rdfs:subClassOf :ValidationConstraint ;
  rdfs:label "SHACL Constraint" ;
  rdfs:comment "A SHACL constraint for validation of invoice data." .

:PivotOrganizationRoleAssignment a owl:Class ;
  rdfs:label "Organization Role Assignment (Pivot)" ;
  rdfs:comment "Reifies the assignment of an AgentRole to an Organization in an Invoice context." .

#################################################################
# Disjointness & DisjointUnion
#################################################################

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:Organization owl:disjointWith :Segment .
:AgentRole owl:disjointWith :Organization .
:PivotOrganizationRoleAssignment owl:disjointWith :Organization .

[ owl:disjointUnionOf ( :AgentRole :BuyerRole :DeliveryPartyRole ) ] .

