{"owl_content": "@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#StoryID> a owl:Ontology ;
  rdfs:label "EDIFACT INVOIC Deep Structured Ontology" ;
  rdfs:comment "A profoundly structured ontology for UN/EDIFACT INVOIC messages, including D96A/EANCOM, EN16931, and P2P-O alignment." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "Top-level envelope containing all messages in an EDIFACT interchange." .

:Message a owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A contained message within an interchange envelope." .

:InvoiceMessage a owl:Class ;
  rdfs:subClassOf :Message ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An invoice (INVOIC) message in the interchange." .

:Section a owl:Class ;
  rdfs:label "Section" ;
  rdfs:comment "A general section in the invoice, superclass of HeaderSection, DetailSection, SummarySection." .

:HeaderSection a owl:Class ;
  rdfs:subClassOf :Section , :InvoiceMessage ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of the invoice, containing dates and reference numbers." .

:DetailSection a owl:Class ;
  rdfs:subClassOf :Section , :InvoiceMessage ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing line items." .

:SummarySection a owl:Class ;
  rdfs:subClassOf :Section , :InvoiceMessage ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section with totals and taxes." .

:Segment a owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within a message, such as BGM or NAD." .

:BGM a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Beginning of Message Segment" ;
  rdfs:comment "The BGM segment identifying the document type and number." .

:NAD a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Name and Address Segment" ;
  rdfs:comment "The NAD segment for participant details (e.g., buyer, supplier)." .

:CompositeDataElement a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple, atomic data element." .

:Organization a owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "Any organization involved in the invoice transaction." .

:AgentRole a owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization in the invoice context." .

:BuyerRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Buyer Role" ;
  rdfs:comment "The buyer role in the invoice." .

:DeliveryPartyRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Delivery Party Role" ;
  rdfs:comment "The delivery party role in the invoice." .

:Address a owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "A postal address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A GLN identifier for an organization location." .

:Item a owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "A line item in the invoice." .

:Price a owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "The price of an item." .

:Quantity a owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "The quantity of an item." .

:Tax a owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax information in the summary section." .

:InvoiceAmount a owl:Class ;
  rdfs:label "Invoice Amount" ;
  rdfs:comment "The total amount of the invoice." .

:InvoiceNumber a owl:Class ;
  rdfs:label "Invoice Number" ;
  rdfs:comment "The invoice's unique identifier." .

:BusinessProcess a owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "A business process to which the invoice is assigned." .

:P2PAlignment a owl:Class ;
  rdfs:label "P2P-O Alignment" ;
  rdfs:comment "Alignment with the Purchase-to-Pay Ontology." .

:EN16931Alignment a owl:Class ;
  rdfs:label "EN 16931 Alignment" ;
  rdfs:comment "Alignment with the European Standard EN 16931-1." .

:ValidationConstraint a owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "A constraint for automated validation (e.g., SHACL)." .

:SHACLConstraint a owl:Class ;
  rdfs:subClassOf :ValidationConstraint ;
  rdfs:label "SHACL Constraint" ;
  rdfs:comment "A SHACL constraint for validation of invoice data." .

:PivotOrganizationRoleAssignment a owl:Class ;
  rdfs:label "Organization Role Assignment (Pivot)" ;
  rdfs:comment "Reifies the assignment of an AgentRole to an Organization in an Invoice context." .

#################################################################
# Disjointness & DisjointUnion
#################################################################

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:Organization owl:disjointWith :Segment .
:AgentRole owl:disjointWith :Organization .
:PivotOrganizationRoleAssignment owl:disjointWith :Organization .

[ owl:disjointUnionOf ( :AgentRole :BuyerRole :DeliveryPartyRole ) ] .

#################################################################
# Object Properties
#################################################################

:hasMessage a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "has message" ;
  rdfs:comment "Links an InterchangeEnvelope to its contained Message." ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  owl:inverseOf :isMessageOf .

:isMessageOf a owl:ObjectProperty ;
  rdfs:label "is message of" ;
  rdfs:comment "Inverse of hasMessage." ;
  rdfs:domain :Message ;
  rdfs:range :InterchangeEnvelope .

:containsSegment a owl:ObjectProperty ;
  rdfs:label "contains segment" ;
  rdfs:comment "Links a Message to its Segments." ;
  rdfs:domain :Message ;
  rdfs:range :Segment ;
  owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
  rdfs:label "is segment of" ;
  rdfs:comment "Inverse of containsSegment." ;
  rdfs:domain :Segment ;
  rdfs:range :Message .

:hasSection a owl:ObjectProperty ;
  rdfs:label "has section" ;
  rdfs:comment "Links an InvoiceMessage to its Header, Detail, or Summary sections." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :Section ;
  owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
  rdfs:label "is section of" ;
  rdfs:comment "Inverse of hasSection." ;
  rdfs:domain :Section ;
  rdfs:range :InvoiceMessage .

:hasRoleAssignment a owl:ObjectProperty ;
  rdfs:label "has role assignment" ;
  rdfs:comment "Links an Organization to its role assignment pivot." ;
  rdfs:domain :Organization ;
  rdfs:range :PivotOrganizationRoleAssignment ;
  owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
  rdfs:label "is role assignment of" ;
  rdfs:comment "Inverse of hasRoleAssignment." ;
  rdfs:domain :PivotOrganizationRoleAssignment ;
  rdfs:range :Organization .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "assigned role" ;
  rdfs:comment "Links a role assignment pivot to an AgentRole." ;
  rdfs:domain :PivotOrganizationRoleAssignment ;
  rdfs:range :AgentRole ;
  owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
  rdfs:label "is role of assignment" ;
  rdfs:comment "Inverse of assignedRole." ;
  rdfs:domain :AgentRole ;
  rdfs:range :PivotOrganizationRoleAssignment .

:roleInInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "role in invoice" ;
  rdfs:comment "Links a role assignment pivot to the InvoiceMessage context." ;
  rdfs:domain :PivotOrganizationRoleAssignment ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :isRoleAssignmentInInvoice .

:isRoleAssignmentInInvoice a owl:ObjectProperty ;
  rdfs:label "is role assignment in invoice" ;
  rdfs:comment "Inverse of roleInInvoice." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :PivotOrganizationRoleAssignment .

:hasAddress a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "has address" ;
  rdfs:comment "Links an Organization to its Address." ;
  rdfs:domain :Organization ;
  rdfs:range :Address ;
  owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
  rdfs:label "is address of" ;
  rdfs:comment "Inverse of hasAddress." ;
  rdfs:domain :Address ;
  rdfs:range :Organization .

:hasGLN a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "has GLN" ;
  rdfs:comment "Links an Organization to its Global Location Number." ;
  rdfs:domain :Organization ;
  rdfs:range :GlobalLocationNumber ;
  owl:inverseOf :isGLNOf .

:isGLNOf a owl:ObjectProperty ;
  rdfs:label "is GLN of" ;
  rdfs:comment "Inverse of hasGLN." ;
  rdfs:domain :GlobalLocationNumber ;
  rdfs:range :Organization .

:hasItem a owl:ObjectProperty ;
  rdfs:label "has item" ;
  rdfs:comment "Links a DetailSection to an Item." ;
  rdfs:domain :DetailSection ;
  rdfs:range :Item ;
  owl:inverseOf :isItemOf .

:isItemOf a owl:ObjectProperty ;
  rdfs:label "is item of" ;
  rdfs:comment "Inverse of hasItem." ;
  rdfs:domain :Item ;
  rdfs:range :DetailSection .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "has price" ;
  rdfs:comment "Links an Item to its Price." ;
  rdfs:domain :Item ;
  rdfs:range :Price ;
  owl:inverseOf :isPriceOf .

:isPriceOf a owl:ObjectProperty ;
  rdfs:label "is price of" ;
  rdfs:comment "Inverse of hasPrice." ;
  rdfs:domain :Price ;
  rdfs:range :Item .

:hasQuantity a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "has quantity" ;
  rdfs:comment "Links an Item to its Quantity." ;
  rdfs:domain :Item ;
  rdfs:range :Quantity ;
  owl:inverseOf :isQuantityOf .

:isQuantityOf a owl:ObjectProperty ;
  rdfs:label "is quantity of" ;
  rdfs:comment "Inverse of hasQuantity." ;
  rdfs:domain :Quantity ;
  rdfs:range :Item .

:hasTax a owl:ObjectProperty ;
  rdfs:label "has tax" ;
  rdfs:comment "Links a SummarySection to its Tax." ;
  rdfs:domain :SummarySection ;
  rdfs:range :Tax ;
  owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
  rdfs:label "is tax of" ;
  rdfs:comment "Inverse of hasTax." ;
  rdfs:domain :Tax ;
  rdfs:range :SummarySection .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "has invoice amount" ;
  rdfs:comment "Links a SummarySection to its InvoiceAmount." ;
  rdfs:domain :SummarySection ;
  rdfs:range :InvoiceAmount ;
  owl:inverseOf :isInvoiceAmountOf .

:isInvoiceAmountOf a owl:ObjectProperty ;
  rdfs:label "is invoice amount of" ;
  rdfs:comment "Inverse of hasInvoiceAmount." ;
  rdfs:domain :InvoiceAmount ;
  rdfs:range :SummarySection .

:hasInvoiceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "has invoice number" ;
  rdfs:comment "Links an InvoiceMessage to its InvoiceNumber." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :InvoiceNumber ;
  owl:inverseOf :isInvoiceNumberOf .

:isInvoiceNumberOf a owl:ObjectProperty ;
  rdfs:label "is invoice number of" ;
  rdfs:comment "Inverse of hasInvoiceNumber." ;
  rdfs:domain :InvoiceNumber ;
  rdfs:range :InvoiceMessage .

:alignedWithP2P a owl:ObjectProperty ;
  rdfs:label "aligned with P2P-O" ;
  rdfs:comment "Alignment of InvoiceMessage with P2P-O." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :P2PAlignment ;
  owl:inverseOf :isP2PAlignmentOf .

:isP2PAlignmentOf a owl:ObjectProperty ;
  rdfs:label "is P2P alignment of" ;
  rdfs:comment "Inverse of alignedWithP2P." ;
  rdfs:domain :P2PAlignment ;
  rdfs:range :InvoiceMessage .

:alignedWithEN16931 a owl:ObjectProperty ;
  rdfs:label "aligned with EN16931" ;
  rdfs:comment "Alignment of InvoiceMessage with EN16931." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :EN16931Alignment ;
  owl:inverseOf :isEN16931AlignmentOf .

:isEN16931AlignmentOf a owl:ObjectProperty ;
  rdfs:label "is EN16931 alignment of" ;
  rdfs:comment "Inverse of alignedWithEN16931." ;
  rdfs:domain :EN16931Alignment ;
  rdfs:range :InvoiceMessage .

:validatedBy a owl:ObjectProperty ;
  rdfs:label "validated by" ;
  rdfs:comment "Links an InvoiceMessage to a ValidationConstraint." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :ValidationConstraint ;
  owl:inverseOf :validates .

:validates a owl:ObjectProperty ;
  rdfs:label "validates" ;
  rdfs:comment "Inverse of validatedBy." ;
  rdfs:domain :ValidationConstraint ;
  rdfs:range :InvoiceMessage .

:assignedToBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:label "assigned to business process" ;
  rdfs:comment "Links an InvoiceMessage to a BusinessProcess." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :BusinessProcess ;
  owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
  rdfs:label "is business process of" ;
  rdfs:comment "Inverse of assignedToBusinessProcess." ;
  rdfs:domain :BusinessProcess ;
  rdfs:range :InvoiceMessage .

#################################################################
# Data Properties
#################################################################

:date a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "date" ;
  rdfs:comment "A date value in the header section." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string .

:referenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "reference number" ;
  rdfs:comment "A reference number in the header section." ;
  rdfs:domain :HeaderSection ;
