  rdfs:domain :Address ;
  rdfs:range xsd:string .

:postalCode a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "postal code" ;
  rdfs:comment "Postal code of an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .

:city a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "city" ;
  rdfs:comment "City of an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .

:country a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "country" ;
  rdfs:comment "Country of an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .

:glnCode a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "GLN code" ;
  rdfs:comment "GLN string value." ;
  rdfs:domain :GlobalLocationNumber ;
  rdfs:range xsd:string .

:itemDescription a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "item description" ;
