  rdfs:label "net price" ;
  rdfs:comment "Net price of an item." ;
  rdfs:domain :Price ;
  rdfs:range xsd:decimal .

:quantityValue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "quantity value" ;
  rdfs:comment "Quantity value of an item." ;
  rdfs:domain :Quantity ;
  rdfs:range xsd:decimal .

:taxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:label "tax amount" ;
  rdfs:comment "Tax amount in the summary section." ;
  rdfs:domain :Tax ;
  rdfs:range xsd:decimal .

