  rdfs:domain :SummarySection ;
  rdfs:range :Tax .

:hasInvoiceAmount a owl:ObjectProperty ;
  rdfs:label "has invoice amount" ;
  rdfs:comment "Links a SummarySection to its InvoiceAmount." ;
  rdfs:domain :SummarySection ;
  rdfs:range :InvoiceAmount ;
  owl:FunctionalProperty .

:hasInvoiceNumber a owl:ObjectProperty ;
  rdfs:label "has invoice number" ;
  rdfs:comment "Links an InvoiceMessage to its InvoiceNumber." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :InvoiceNumber ;
  owl:FunctionalProperty .

:alignedWithP2P a owl:ObjectProperty ;
  rdfs:label "aligned with P2P-O" ;
  rdfs:comment "Alignment of InvoiceMessage with P2P-O." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :P2PAlignment .

:alignedWithEN16931 a owl:ObjectProperty ;
  rdfs:label "aligned with EN16931" ;
  rdfs:comment "Alignment of InvoiceMessage with EN16931." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :EN16931Alignment .

:validatedBy a owl:ObjectProperty ;
  rdfs:label "validated by" ;
  rdfs:comment "Links an InvoiceMessage to a ValidationConstraint." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :ValidationConstraint .

:assignedToBusinessProcess a owl:ObjectProperty ;
  rdfs:label "assigned to business process" ;
  rdfs:comment "Links an InvoiceMessage to a BusinessProcess." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :BusinessProcess ;
  owl:FunctionalProperty .

#################################################################
# Data Properties
#################################################################

:date a owl:DatatypeProperty ;
  rdfs:label "date" ;
  rdfs:comment "A date value in the header section." ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string ;
  owl:FunctionalProperty .

