#################################################################
# Complex Axioms & Restrictions
#################################################################

:InvoiceMessage owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    :Message
    [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :HeaderSection ]
    [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :DetailSection ]
    [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :SummarySection ]
    [ a owl:Restriction ; owl:onProperty :hasInvoiceNumber ; owl:someValuesFrom :InvoiceNumber ]
    [ a owl:Restriction ; owl:onProperty :assignedToBusinessProcess ; owl:someValuesFrom :BusinessProcess ]
  )
] .

:Organization owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    [ a owl:Restriction ; owl:onProperty :hasRoleAssignment ; owl:someValuesFrom :PivotOrganizationRoleAssignment ]
    [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:someValuesFrom :Address ]
    [ a owl:Restriction ; owl:onProperty :hasGLN ; owl:someValuesFrom :GlobalLocationNumber ]
  )
] .

:PivotOrganizationRoleAssignment owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf (
    [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:someValuesFrom :AgentRole ]
    [ a owl:Restriction ; owl:onProperty :roleInInvoice ; owl:someValuesFrom :InvoiceMessage ]
  )
] .

