@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/storyid> a owl:Ontology ;
  rdfs:label "EDIFACT INVOIC Ontology" ;
  rdfs:comment "A deep ontology for UN/EDIFACT D96A INVOIC messages, with EANCOM, EN 16931-1, and P2P-O alignment." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope a owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "The outermost envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
  rdfs:subClassOf :Message ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An EDIFACT INVOIC message for global trade transactions." .

:Segment a owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "The Beginning of Message segment for document identification." .

:NADSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "The Name and Address segment for participant details." .

:CompositeDataElement a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "Composite data element containing simple elements." .

:SimpleDataElement a owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "Atomic data element within a composite." .

:HeaderSection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Header Section" ;
  rdfs:comment "The header section of an invoice message, containing document dates and reference numbers." .

:DetailSection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Detail Section" ;
  rdfs:comment "The detail section listing line items with prices and quantities." .

:SummarySection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Summary Section" ;
  rdfs:comment "The summary section providing total tax and invoice amounts." .

:Organization a owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "A business entity involved in the invoice, e.g., buyer, supplier, delivery party." .

:AgentRole a owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization in a transaction." .

:BuyerRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Buyer Role" ;
  rdfs:comment "The role of buyer in a transaction." .

:DeliveryPartyRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Delivery Party Role" ;
  rdfs:comment "The role of delivery party in a transaction." .

:Address a owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "An address associated with an organization or role." .

:GlobalLocationNumber a owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A unique identifier for a location, such as a warehouse or headquarters." .

:Item a owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "A product or good being invoiced." .

:Price a owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "A monetary value assigned to an item." .

:Quantity a owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "The amount of an item listed in the invoice." .

:Tax a owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "A tax applied to the invoice or line item." .

:ReferenceNumber a owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "A reference number in the document header." .

:BusinessProcess a owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "A constraint for automated validation, e.g., SHACL rules." .

:InvoiceLine a owl:Class ;
  rdfs:label "Invoice Line" ;
  rdfs:comment "A line item in the invoice." .

:InvoiceAmount a owl:Class ;
  rdfs:label "Invoice Amount" ;
  rdfs:comment "The total amount of the invoice." .

:InvoiceNumber a owl:Class ;
  rdfs:label "Invoice Number" ;
  rdfs:comment "The unique number of the invoice." .

:Identifier a owl:Class ;
  rdfs:label "Identifier" ;
  rdfs:comment "A generic identifier (e.g. for organizations, addresses)." .

# Pivot Classes
:OrganizationRoleAssignment a owl:Class ;
  rdfs:label "Organization Role Assignment" ;
  rdfs:comment "Reifies the assignment of an AgentRole to an Organization, possibly with context." .

:InvoiceLineItem a owl:Class ;
  rdfs:label "Invoice Line Item" ;
  rdfs:comment "A reified line item linking item, price, and quantity." .

#################################################################
# Class Hierarchy Axioms
#################################################################
:BuyerRole owl:disjointWith :DeliveryPartyRole .
:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Item owl:disjointWith :Organization .
:Segment owl:disjointWith :Organization .

:AgentRole owl:disjointUnionOf ( :BuyerRole :DeliveryPartyRole ) .

#################################################################
# Properties & Inverses
#################################################################
:containsMessage a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  rdfs:label "contains message" ;
  rdfs:comment "Links an envelope to the message(s) it contains." ;
  owl:inverseOf :isContainedInEnvelope .
:isContainedInEnvelope a owl:ObjectProperty ;
  rdfs:domain :Message ;
  rdfs:range :InterchangeEnvelope ;
  rdfs:label "is contained in envelope" ;
  rdfs:comment "Inverse: Message is contained in envelope." ;
  owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
  rdfs:domain :Message ;
  rdfs:range :Segment ;
  rdfs:label "has segment" ;
  rdfs:comment "Links a message to its segments." ;
  owl:inverseOf :isSegmentOf .
:isSegmentOf a owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :Message ;
  rdfs:label "is segment of" ;
  rdfs:comment "Inverse: Segment is part of message." ;
  owl:inverseOf :hasSegment .

:hasSection a owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range [ owl:unionOf ( :HeaderSection :DetailSection :SummarySection ) ] ;
  rdfs:label "has section" ;
  rdfs:comment "Links an invoice message to its logical sections." ;
  owl:inverseOf :isSectionOf .
:isSectionOf a owl:ObjectProperty ;
  rdfs:domain [ owl:unionOf ( :HeaderSection :DetailSection :SummarySection ) ] ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is section of" ;
  rdfs:comment "Inverse: Section is part of invoice message." ;
  owl:inverseOf :hasSection .

:hasCompositeElement a owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :CompositeDataElement ;
  rdfs:label "has composite element" ;
  rdfs:comment "Links a segment to its composite data elements." ;
  owl:inverseOf :isCompositeElementOf .
:isCompositeElementOf a owl:ObjectProperty ;
  rdfs:domain :CompositeDataElement ;
  rdfs:range :Segment ;
  rdfs:label "is composite element of" ;
  rdfs:comment "Inverse: Composite data element is part of segment." ;
  owl:inverseOf :hasCompositeElement .

:hasSimpleElement a owl:ObjectProperty ;
  rdfs:domain :CompositeDataElement ;
  rdfs:range :SimpleDataElement ;
  rdfs:label "has simple element" ;
  rdfs:comment "Links a composite element to its simple data elements." ;
  owl:inverseOf :isSimpleElementOf .
:isSimpleElementOf a owl:ObjectProperty ;
  rdfs:domain :SimpleDataElement ;
  rdfs:range :CompositeDataElement ;
  rdfs:label "is simple element of" ;
  rdfs:comment "Inverse: Simple data element is part of composite." ;
  owl:inverseOf :hasSimpleElement .

:playsRole a owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :AgentRole ;
  rdfs:label "plays role" ;
  rdfs:comment "Indicates the role played by an organization." ;
  owl:inverseOf :isRoleOf .
:isRoleOf a owl:ObjectProperty ;
  rdfs:domain :AgentRole ;
  rdfs:range :Organization ;
  rdfs:label "is role of" ;
  rdfs:comment "Inverse: Role is played by organization." ;
  owl:inverseOf :playsRole .

:hasAddress a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :Organization ;
  rdfs:range :Address ;
  rdfs:label "has address" ;
  rdfs:comment "Links an organization to its address." ;
  owl:inverseOf :isAddressOf .
:isAddressOf a owl:ObjectProperty ;
  rdfs:domain :Address ;
  rdfs:range :Organization ;
  rdfs:label "is address of" ;
  rdfs:comment "Inverse: Address is for organization." ;
  owl:inverseOf :hasAddress .

:hasGlobalLocationNumber a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :Organization ;
  rdfs:range :GlobalLocationNumber ;
  rdfs:label "has global location number" ;
  rdfs:comment "Links an organization to its GLN." ;
  owl:inverseOf :isGLNOf .
:isGLNOf a owl:ObjectProperty ;
  rdfs:domain :GlobalLocationNumber ;
  rdfs:range :Organization ;
  rdfs:label "is GLN of" ;
  rdfs:comment "Inverse: GLN is for organization." ;
  owl:inverseOf :hasGlobalLocationNumber .

:assignedRole a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :OrganizationRoleAssignment ;
  rdfs:range :AgentRole ;
  rdfs:label "assigned role" ;
  rdfs:comment "The agent role assigned in this assignment." ;
  owl:inverseOf :isAssignedRoleOf .
:isAssignedRoleOf a owl:ObjectProperty ;
  rdfs:domain :AgentRole ;
  rdfs:range :OrganizationRoleAssignment ;
  rdfs:label "is assigned role of" ;
  rdfs:comment "Inverse: Role is assigned in assignment." ;
  owl:inverseOf :assignedRole .

:assignedToOrganization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :OrganizationRoleAssignment ;
  rdfs:range :Organization ;
  rdfs:label "assigned to organization" ;
  rdfs:comment "The organization to which the role is assigned." ;
  owl:inverseOf :hasRoleAssignment .
:hasRoleAssignment a owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :OrganizationRoleAssignment ;
  rdfs:label "has role assignment" ;
  rdfs:comment "Inverse: Organization has role assignment." ;
  owl:inverseOf :assignedToOrganization .

:hasInvoiceLine a owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :InvoiceLine ;
  rdfs:label "has invoice line" ;
  rdfs:comment "Links an invoice message to its invoice lines." ;
  owl:inverseOf :isInvoiceLineOf .
:isInvoiceLineOf a owl:ObjectProperty ;
  rdfs:domain :InvoiceLine ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is invoice line of" ;
  rdfs:comment "Inverse: Invoice line is part of invoice message." ;
  owl:inverseOf :hasInvoiceLine .

:hasInvoiceLineItem a owl:ObjectProperty ;
  rdfs:domain :InvoiceLine ;
  rdfs:range :InvoiceLineItem ;
  rdfs:label "has invoice line item" ;
  rdfs:comment "Links an invoice line to its line item." ;
  owl:inverseOf :isInvoiceLineItemOf .
:isInvoiceLineItemOf a owl:ObjectProperty ;
  rdfs:domain :InvoiceLineItem ;
  rdfs:range :InvoiceLine ;
  rdfs:label "is invoice line item of" ;
  rdfs:comment "Inverse: Line item is part of invoice line." ;
  owl:inverseOf :hasInvoiceLineItem .

:refersToItem a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :InvoiceLineItem ;
  rdfs:range :Item ;
  rdfs:label "refers to item" ;
  rdfs:comment "Links a line item to the item being sold." ;
  owl:inverseOf :isItemReferredBy .
:isItemReferredBy a owl:ObjectProperty ;
  rdfs:domain :Item ;
  rdfs:range :InvoiceLineItem ;
  rdfs:label "is item referred by" ;
  rdfs:comment "Inverse: Item is referenced by line item." ;
  owl:inverseOf :refersToItem .

:netPrice a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :InvoiceLineItem ;
  rdfs:range :Price ;
  rdfs:label "net price" ;
  rdfs:comment "The net price of the item in the line item." ;
  owl:inverseOf :isNetPriceOf .
:isNetPriceOf a owl:ObjectProperty ;
  rdfs:domain :Price ;
  rdfs:range :InvoiceLineItem ;
  rdfs:label "is net price of" ;
  rdfs:comment "Inverse: Price is for line item." ;
  owl:inverseOf :netPrice .

:quantity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :InvoiceLineItem ;
  rdfs:range :Quantity ;
  rdfs:label "quantity" ;
  rdfs:comment "The quantity of the item in the line item." ;
  owl:inverseOf :isQuantityOf .
:isQuantityOf a owl:ObjectProperty ;
  rdfs:domain :Quantity ;
  rdfs:range :InvoiceLineItem ;
  rdfs:label "is quantity of" ;
  rdfs:comment "Inverse: Quantity is for line item." ;
  owl:inverseOf :quantity .

:tax a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :SummarySection ;
  rdfs:range :Tax ;
  rdfs:label "tax" ;
  rdfs:comment "The tax in the summary section." ;
  owl:inverseOf :isTaxOf .
:isTaxOf a owl:ObjectProperty ;
  rdfs:domain :Tax ;
  rdfs:range :SummarySection ;
  rdfs:label "is tax of" ;
  rdfs:comment "Inverse: Tax is for summary section." ;
  owl:inverseOf :tax .

:invoiceAmount a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :SummarySection ;
  rdfs:range :InvoiceAmount ;
  rdfs:label "invoice amount" ;
  rdfs:comment "The total invoice amount." ;
  owl:inverseOf :isInvoiceAmountOf .
:isInvoiceAmountOf a owl:ObjectProperty ;
  rdfs:domain :InvoiceAmount ;
  rdfs:range :SummarySection ;
  rdfs:label "is invoice amount of" ;
  rdfs:comment "Inverse: Invoice amount is for summary section." ;
  owl:inverseOf :invoiceAmount .

:invoiceNumber a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :HeaderSection ;
  rdfs:range :InvoiceNumber ;
  rdfs:label "invoice number" ;
  rdfs:comment "The invoice number in the header section." ;
  owl:inverseOf :isInvoiceNumberOf .
:isInvoiceNumberOf a owl:ObjectProperty ;
  rdfs:domain :InvoiceNumber ;
  rdfs:range :HeaderSection ;
  rdfs:label "is invoice number of" ;
  rdfs:comment "Inverse: Invoice number is for header section." ;
  owl:inverseOf :invoiceNumber .

:referenceNumber a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :HeaderSection ;
  rdfs:range :ReferenceNumber ;
  rdfs:label "reference number" ;
  rdfs:comment "A reference number in the header section." ;
  owl:inverseOf :isReferenceNumberOf .
:isReferenceNumberOf a owl:ObjectProperty ;
  rdfs:domain :ReferenceNumber ;
  rdfs:range :HeaderSection ;
  rdfs:label "is reference number of" ;
  rdfs:comment "Inverse: Reference number is for header section." ;
  owl:inverseOf :referenceNumber .

:identifier a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :Organization ;
  rdfs:range :Identifier ;
  rdfs:label "identifier" ;
  rdfs:comment "A generic identifier for the organization." ;
  owl:inverseOf :isIdentifierOf .
:isIdentifierOf a owl:ObjectProperty ;
  rdfs:domain :Identifier ;
  rdfs:range :Organization ;
  rdfs:label "is identifier of" ;
  rdfs:comment "Inverse: Identifier is for organization." ;
  owl:inverseOf :identifier .

:businessProcess a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :BusinessProcess ;
  rdfs:label "business process" ;
  rdfs:comment "The business process to which the invoice is assigned." ;
  owl:inverseOf :isBusinessProcessOf .
:isBusinessProcessOf a owl:ObjectProperty ;
  rdfs:domain :BusinessProcess ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is business process of" ;
  rdfs:comment "Inverse: Business process is for invoice message." ;
  owl:inverseOf :businessProcess .

:mandatoryIdentifier a owl:ObjectProperty ;
  rdfs:domain :ValidationConstraint ;
  rdfs:range :Identifier ;
  rdfs:label "mandatory identifier" ;
  rdfs:comment "A mandatory identifier required for validation." ;
  owl:inverseOf :isMandatoryIdentifierOf .
:isMandatoryIdentifierOf a owl:ObjectProperty ;
  rdfs:domain :Identifier ;
  rdfs:range :ValidationConstraint ;
  rdfs:label "is mandatory identifier of" ;
  rdfs:comment "Inverse: Identifier is required by validation constraint." ;
  owl:inverseOf :mandatoryIdentifier .

#################################################################
# Data Properties
#################################################################
:date a owl:DatatypeProperty ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string ;
  rdfs:label "date" ;
  rdfs:comment "A date value in the header section (ISO string)." .

#################################################################
# Restrictions & GCAs
#################################################################
:InvoiceLineItem rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :refersToItem ; owl:cardinality "1"^^xsd:nonNegativeInteger ] ,
                                   [ a owl:Restriction ; owl:onProperty :netPrice ; owl:cardinality "1"^^xsd:nonNegativeInteger ] ,
                                   [ a owl:Restriction ; owl:onProperty :quantity ; owl:cardinality "1"^^xsd:nonNegativeInteger ] .

[ a owl:Class ; owl:equivalentClass [ a owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :BuyerRole ] ; rdfs:subClassOf :Organization ] .

:ValidationConstraint rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :mandatoryIdentifier ; owl:someValuesFrom :Identifier ] .

