@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_INVOIC_Ontology> a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "A deep ontology for EDIFACT INVOIC messages, organizations, roles, and business context, aligned to D96A and EN 16931-1." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The envelope that contains one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An EDIFACT INVOIC message representing an invoice transaction." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a composite element or segment." .

:InvoiceHeader a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of the invoice containing document dates and references." .

:InvoiceDetail a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section listing line items of the invoice." .

:InvoiceSummary a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section providing totals for tax and invoice amount." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice process." .

:OrganizationRole a owl:Class ;
    rdfs:label "Organization Role" ;
    rdfs:comment "A role played by an organization in the context of an invoice (e.g., Buyer, Delivery Party)." .

:BuyerRole a owl:Class ;
    rdfs:subClassOf :OrganizationRole ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "Role of an organization as the buyer." .

:DeliveryPartyRole a owl:Class ;
    rdfs:subClassOf :OrganizationRole ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "Role of an organization as the delivery party." .

:AgentRoleAssignment a owl:Class ;
    rdfs:label "Agent Role Assignment" ;
    rdfs:comment "Reifies the assignment of a role and address to an organization in a specific invoice context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "An address associated with an organization role." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service sold in the invoice." .

:ItemLine a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Item Line" ;
    rdfs:comment "A line in the invoice detail referring to a specific item, its price, and quantity." .

:Price a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Price" ;
    rdfs:comment "A composite element representing price information." .

:Tax a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Tax" ;
    rdfs:comment "A composite element representing tax information." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number for identifying the invoice or related documents." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:P2PElement a owl:Class ;
    rdfs:label "Purchase-to-Pay Element" ;
    rdfs:comment "Element from the Purchase-to-Pay Ontology (P2P-O)." .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to the messages it contains." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Associates a message with its constituent segments." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Associates a segment with its composite data elements." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Associates a composite element with its simple data elements." .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeader ;
    rdfs:label "has header" ;
    rdfs:comment "Links an invoice message to its header section." .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceDetail ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an invoice message to its detail section." .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceSummary ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an invoice message to its summary section." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Indicates organizations involved in the invoice." .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AgentRoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an invoice message to its role assignments (reification of agent roles)." .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :AgentRoleAssignment ;
    rdfs:range :OrganizationRole ;
    rdfs:label "assigned role" ;
    rdfs:comment "The role assigned to an organization in a specific context." .

:assignedOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :AgentRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "assigned organization" ;
    rdfs:comment "The organization assigned a specific role." .

:assignedAddress a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :AgentRoleAssignment ;
    rdfs:range :Address ;
    rdfs:label "assigned address" ;
    rdfs:comment "The address associated with an organization's role in a context." .

:hasItemLine a owl:ObjectProperty ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :ItemLine ;
    rdfs:label "has item line" ;
    rdfs:comment "Links the invoice detail to its item lines." .

:describesItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links an item line to the item it describes." .

:hasNetPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links an item line to its net price." .

:hasTotalTax a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Tax ;
    rdfs:label "has total tax" ;
    rdfs:comment "Links invoice summary to total tax." .

:assignedToProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Assigns the invoice to a business process." .

:hasP2PElement a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :P2PElement ;
    rdfs:label "has P2P element" ;
    rdfs:comment "Links invoice to elements from the Purchase-to-Pay ontology." .

#################################################################
# Data Properties
#################################################################

:hasGLN a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has GLN" ;
    rdfs:comment "The Global Location Number of the organization." .

:hasReferenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number" ;
    rdfs:comment "Reference number of the invoice." .

:hasInvoiceDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice date" ;
    rdfs:comment "The date of the invoice. Use xsd:string for compliance." .

:hasQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "Quantity of the item in the item line." .

:hasInvoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Total invoice amount." .

#################################################################
# Class Disjointness
#################################################################

:OrganizationRole owl:disjointWith :Segment .
:Organization owl:disjointWith :Segment .
:Item owl:disjointWith :Organization .
:InvoiceHeader owl:disjointWith :InvoiceDetail .
:InvoiceDetail owl:disjointWith :InvoiceSummary .

#################################################################
# General Class Axioms & Restrictions
#################################################################

:BuyerRole owl:equivalentClass [
    a owl:Restriction ;
    owl:onProperty :assignedRole ;
    owl:allValuesFrom :BuyerRole
] .

:InvoiceMessage rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasHeader ;
    owl:someValuesFrom :InvoiceHeader
] , [
    a owl:Restriction ;
    owl:onProperty :hasDetail ;
    owl:someValuesFrom :InvoiceDetail
] , [
    a owl:Restriction ;
    owl:onProperty :hasSummary ;
    owl:someValuesFrom :InvoiceSummary
] .

:AgentRoleAssignment rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :assignedRole ;
    owl:someValuesFrom :OrganizationRole
] , [
