    rdfs:comment "An Organization that acts as Buyer in a role assignment." ;
    owl:equivalentClass [
      a owl:Class ;
      owl:intersectionOf (
        :Organization
        [ owl:hasSelf true ; owl:onProperty [
            owl:inverseOf :hasParticipant
